CREATE TABLE [dbo].[ccRIAChatInboundMsgs](	  [msg_id] INT NOT NULL	, [Inbound_id] SMALLINT NOT NULL	, [orden] TINYINT NOT NULL	, [type] TINYINT NOT NULL)ALTER TABLE [dbo].[ccRIAChatInboundMsgs] WITH CHECK ADD CONSTRAINT [fk_Inbound] FOREIGN KEY([Inbound_id]) REFERENCES [dbo].[ccInbound] ([Inbound_id])ALTER TABLE [dbo].[ccRIAChatInboundMsgs] CHECK CONSTRAINT [fk_Inbound]ALTER TABLE [dbo].[ccRIAChatInboundMsgs] WITH CHECK ADD CONSTRAINT [fk_MsgChat] FOREIGN KEY([msg_id]) REFERENCES [dbo].[ccRIAChatMsg] ([msg_id])ALTER TABLE [dbo].[ccRIAChatInboundMsgs] CHECK CONSTRAINT [fk_MsgChat]ALTER TABLE [dbo].[ccRIAChatInboundMsgs] WITH CHECK ADD CONSTRAINT [fk_TipoMsgs] FOREIGN KEY([type]) REFERENCES [dbo].[ccTipoMsgs] ([tipomsg_id])ALTER TABLE [dbo].[ccRIAChatInboundMsgs] CHECK CONSTRAINT [fk_TipoMsgs]CREATE UNIQUE NONCLUSTERED INDEX [IX_ccInboundMsgs] ON [dbo].[ccRIAChatInboundMsgs] ([msg_id] ASC, [Inbound_id] ASC, [orden] ASC, [type] ASC)